    def _select(self, cands, t0, x0, z0):
        n = len(cands)
        score = [None] * n
        prev = [-1] * n
        for i, c in enumerate(cands):
            nominal = float(c.hit_time) - LAG
            tol = self._tol(c)
            xs = self._x_start(c)
            best = None
            arr = t0 + self._need(z0, abs(xs - x0), K_MAX)
            if arr <= nominal + tol:
                best = (1.0 - 0.01 * max(0.0, arr - nominal), -1)
            for j in range(i):
                if score[j] is None:
                    continue
                m = cands[j]
                if float(m.hit_time) >= float(c.hit_time):
                    continue
                arr = self._end_min(m) + self._need(
                    self.press_z, abs(xs - self._x_end(m)), K_MAX)
                if arr <= nominal + tol:
                    v = score[j] + 1.0 - 0.01 * max(0.0, arr - nominal)
                    if best is None or v > best[0]:
                        best = (v, j)
            if best is not None:
                score[i], prev[i] = best
        bi, bv = -1, None
        for i in range(n):
            if score[i] is not None and (bv is None or score[i] > bv + 1e-9):
                bi, bv = i, score[i]
        chain = []
        while bi >= 0:
            chain.append(cands[bi])
            bi = prev[bi]
        chain.reverse()
        return chain
