    def _plan(self, cur, notes, t_now):
        api = self.api
        cx = self._clip(float(cur.x))
        cz = float(cur.z)

        bykey = {}
        for n in list(notes or []):
            try:
                _ = n.key, n.hit_time, n.lane
            except Exception:
                continue
            if not self._on_my_side(n):
                continue
            bykey[n.key] = n

        self.committed = {k for k in self.committed
                          if k in bykey and not self._finished(bykey[k], t_now)}
        forced = sorted((bykey[k] for k in self.committed),
                        key=lambda n: float(n.hit_time))

        if forced:
            f = forced[-1]
            t0 = max(t_now, self._end_min(f))
            x0, z0 = self._x_end(f), self.press_z
            last_hit = float(f.hit_time)
        else:
            t0, x0, z0 = t_now, cx, cz
            last_hit = -1e9

        cands = []
        for n in bykey.values():
            if n.key in self.committed:
                continue
            h = float(n.hit_time)
            if h <= last_hit or h > t_now + PLAN_HORIZON:
                continue
            if h - LAG + self._tol(n) < t_now:
                continue
            if self._end(n) < t_now:
                continue
            cands.append(n)
        cands.sort(key=lambda n: (float(n.hit_time), self._end(n)))

        chain = forced + self._select(cands, t0, x0, z0)
        return self._build(cur, chain, t_now, cx, cz)
